package com.wisal.app

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

private val wisalImages = mapOf(
"SPLASH_ART" to "",
"MOSQUE_STORY" to "",
"AVATAR_PROFILE" to "",
"GROUP_ICON" to ""
)

@Composable
fun WisalPosterImage(name: String, modifier: Modifier = Modifier, contentScale: ContentScale = ContentScale.Crop) {
    val bitmap = remember(name) {
        val bytes = Base64.decode(wisalImages[name] ?: wisalImages["SPLASH_ART"]!!, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap()
    }
    Image(bitmap = bitmap, contentDescription = null, modifier = modifier, contentScale = contentScale)
}
